def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            area = (maxr - minr + 1) * (maxc - minc + 1)
            if area >= 10 and len(cells) / area >= 0.65:
                objects.append((color, minr, maxr, minc, maxc))

    out = [[bg for _ in range(w)] for _ in range(h)]
    for color, minr, maxr, minc, maxc in objects:
        for r in range(minr, maxr + 1):
            for c in range(minc, maxc + 1):
                out[r][c] = color
    return out
